"use client";

import React, { useEffect, useState } from "react";
import Link from "next/link";
import Image from "next/image";
import { navLinks } from "@/constants";
import { logo, menu, close } from "@/assets";
import { styles } from "@/styles/styles";

const Navbar = () => {
    const [active, setActive] = useState("");
    const [toggle, setToggle] = useState(false);
    const [scrolled, setScrolled] = useState(false);

    useEffect(() => {
        const handleScroll = () => {
            const scrollTop = window.scrollY;
            if (scrollTop > 100) {
                setScrolled(true);
            } else {
                setScrolled(false);
            }
        };

        window.addEventListener("scroll", handleScroll);
        return () => window.removeEventListener("scroll", handleScroll);
    }, []);

    return (
        <nav
            className={`${styles.paddingX
                } w-full flex items-center py-5 fixed top-0 z-20 ${scrolled ? "bg-primary/80 backdrop-blur-md" : "bg-transparent"
                } transition-all duration-300`}
        >
            <div className='w-full flex justify-between items-center max-w-7xl mx-auto'>
                <Link
                    href='/'
                    className='flex items-center gap-2'
                    onClick={() => {
                        setActive("");
                        window.scrollTo(0, 0);
                    }}
                >
                    <Image src={logo} alt='logo' width={36} height={36} className='object-contain' />
                    <p className='text-white-100 text-[18px] font-bold cursor-pointer flex '>
                        Sohan &nbsp;
                        <span className='sm:block hidden'> | Paliyal</span>
                    </p>
                </Link>

                <ul className='list-none hidden sm:flex flex-row gap-10'>
                    {navLinks.map((nav) => (
                        <li
                            key={nav.id}
                            className={`${active === nav.title ? "text-white-100" : "text-secondary"
                                } hover:text-white-100 text-[18px] font-medium cursor-pointer transition-colors`}
                            onClick={() => setActive(nav.title)}
                        >
                            {nav.id === "blog" ? (
                                <Link href='/blog'>{nav.title}</Link>
                            ) : (
                                <a href={`#${nav.id}`}>{nav.title}</a>
                            )}
                        </li>
                    ))}
                </ul>

                <div className='sm:hidden flex flex-1 justify-end items-center'>
                    <Image
                        src={toggle ? close : menu}
                        alt='menu'
                        width={28}
                        height={28}
                        className='object-contain cursor-pointer'
                        onClick={() => setToggle(!toggle)}
                    />

                    <div
                        className={`${!toggle ? "hidden" : "flex"
                            } p-6 black-gradient absolute top-20 right-0 mx-4 my-2 min-w-[140px] z-10 rounded-xl glassmorphism`}
                    >
                        <ul className='list-none flex justify-end items-start flex-1 flex-col gap-4'>
                            {navLinks.map((nav) => (
                                <li
                                    key={nav.id}
                                    className={`font-poppins font-medium cursor-pointer text-[16px] ${active === nav.title ? "text-white-100" : "text-secondary"
                                        }`}
                                    onClick={() => {
                                        setToggle(!toggle);
                                        setActive(nav.title);
                                    }}
                                >
                                    {nav.id === "blog" ? (
                                        <Link href='/blog'>{nav.title}</Link>
                                    ) : (
                                        <a href={`#${nav.id}`}>{nav.title}</a>
                                    )}
                                </li>
                            ))}
                        </ul>
                    </div>
                </div>
            </div>
        </nav>
    );
};

export default Navbar;
